// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    Attacker attacker;

    function setUp() public { 
        c = new MultiplicatorX3();
        attacker = new Attacker();
    }

    function testFuzz_property(uint256 amount, bytes calldata payload) public {
        amount = bound(amount, 0, 1 ether);

        address owner = address(this);
        vm.deal(owner, amount + 1 ether);

        assertEq(address(c).balance, 0);

        vm.startPrank(owner);
        bool ok;
        try c.Command{value: amount}(address(attacker), payload) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(amount == 0 || ok);
    }
}

contract Attacker {
    receive() external payable {}
}
